108	export function ago(iso, now = Date.now()) {
109	  const minutes = Math.floor(Math.max(0, now - Date.parse(iso)) / 60000);
110	  const count = (n, unit) => `${n} ${unit}${n === 1 ? '' : 's'} ago`;
